import sys, re, requests, time, json
from urllib.parse import quote

session = requests.Session()
session.headers.update({'User-Agent': 'FakeCitationDetector/1.0'})

def clean(text):
    text = re.sub(r'[{}\\]', '', text)
    return re.sub(r'\s+', ' ', text).strip()

def parse_bibtex(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    entries = []
    pattern = r'@(\w+)\s*\{\s*([^,\s]+)\s*,(.*?)\n\}'
    for m in re.finditer(pattern, content, re.DOTALL | re.IGNORECASE):
        fields = {}
        fp = r'(\w+)\s*=\s*\{([^}]*)\}|(\w+)\s*=\s*"([^"]*)"'
        for fm in re.finditer(fp, m.group(3)):
            if fm.group(1):
                fields[fm.group(1).lower()] = clean(fm.group(2))
            else:
                fields[fm.group(3).lower()] = clean(fm.group(4))
        entries.append({'type': m.group(1).lower(), 'key': m.group(2).strip(), 'fields': fields})
    return entries

def verify_doi(doi):
    doi = doi.strip().split()[0]
    try:
        r = session.get(f'https://api.crossref.org/works/{doi}', timeout=15)
        if r.status_code == 200:
            msg = r.json().get('message', {})
            title = msg.get('title', [''])[0] if msg.get('title') else ''
            return True, title
        return False, None
    except:
        return None, None

def norm(t):
    t = t.lower(); t = re.sub(r'[^\w\s]', '', t); return set(t.split())

def search_crossref(title):
    q = f'query.title={quote(title[:200])}&rows=5'
    try:
        r = session.get(f'https://api.crossref.org/works?{q}', timeout=15)
        if r.status_code == 200:
            items = r.json().get('message', {}).get('items', [])
            for item in items:
                it = item.get('title', [''])[0] if item.get('title') else ''
                s1, s2 = norm(title), norm(it)
                sim = len(s1 & s2)/len(s1 | s2) if s1 and s2 else 0
                if sim >= 0.7:
                    return True
            return False
    except: pass
    return None

def search_semantic(title):
    try:
        r = session.get(f'https://api.semanticscholar.org/graph/v1/paper/search?query={quote(title[:200])}&limit=5&fields=title', timeout=15)
        if r.status_code == 200:
            for p in r.json().get('data', []):
                pt = p.get('title', '')
                s1, s2 = norm(title), norm(pt)
                sim = len(s1 & s2)/len(s1 | s2) if s1 and s2 else 0
                if sim >= 0.7:
                    return True
            return False
        elif r.status_code == 429:
            time.sleep(3)
            return search_semantic(title)
    except: pass
    return None

entries = parse_bibtex('/tmp/test.bib')
fake_titles = []

for e in entries:
    f = e['fields']
    k, doi, title = e['key'], f.get('doi',''), f.get('title','')
    print(f"Checking {k}...", flush=True)
    is_fake = False

    if doi:
        exists, _ = verify_doi(doi)
        if exists is False:
            is_fake = True
            print(f"  FAKE (DOI invalid): {doi}")
        elif exists is None:
            # error, try title search as fallback
            t1 = search_crossref(title)
            if t1 is False:
                t2 = search_semantic(title)
                if t2 is False:
                    is_fake = True
                    print("  FAKE (API error, not found by title)")
            elif t1 is None:
                time.sleep(1)
                t2 = search_semantic(title)
                if t2 is False:
                    is_fake = True
        time.sleep(0.3)
    elif title:
        found = search_crossref(title)
        if found is False:
            time.sleep(1)
            found2 = search_semantic(title)
            if found2 is False:
                is_fake = True
                print("  FAKE (not found in CrossRef or Scholar)")
        time.sleep(0.5)
    else:
        is_fake = True

    if is_fake and title:
        fake_titles.append(title)

fake_titles.sort()
print(f"\nTotal entries: {len(entries)}")
print(f"Fake citations ({len(fake_titles)}):")
for t in fake_titles:
    print(f"  - {t}")

with open('/tmp/answer.json', 'w') as out:
    json.dump({'fake_citations': fake_titles}, out, indent=2)
print(f"\nDone. Written to /tmp/answer.json")
ENDSCRIPT
