def parse_bibtex(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    entries = []
    pattern = r'@(\w+)\s*\{\s*([^,\s]+)\s*,(.*?)\n\}'
    for m in re.finditer(pattern, content, re.DOTALL | re.IGNORECASE):
        fields = {}
        fp = r'(\w+)\s*=\s*\{([^}]*)\}|(\w+)\s*=\s*"([^"]*)"'
        for fm in re.finditer(fp, m.group(3)):
            if fm.group(1):
                fields[fm.group(1).lower()] = clean(fm.group(2))
            else:
