# Try pty-based approach with sudo via a pty
import pty
import os
import select

def run_pty(command, password=None):
    master, slave = pty.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.setsid()
        os.dup2(slave, 0)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.execvp('/bin/bash', ['bash', '-c', command])
    else:
        os.close(slave)
        output = b""
        import time
        while True:
            r, _, _ = select.select([master], [], [], 2)
            if r:
                try:
                    data = os.read(master, 4096)
                except OSError:
                    break
                output += data
                print(data.decode('utf-8', errors='replace'), end='')
                if b'[sudo]' in output or b'password' in output.lower():
                    if password:
                        time.sleep(0.5)
                        os.write(master, (password + '\n').encode())
                if output.rstrip().endswith(b'$ ') or output.rstrip().endswith(b'# '):
