{"content": "// Global state
let selectedTicker = null;
let stockData = [];

// Color scale for sectors
const sectorColors = {
    'Energy': '#80b1d3',
    'Financial': '#fdb462',
    'Industry': '#b3de69',
    'Information Technology': '#fccde5',
    'ETF': '#d9d9d9'
};

// Format market cap to human readable
function formatMarketCap(val) {
    if (val == null || val === 0 || val === 'null' || val === undefined) return 'N/A';
    const num = +val;
    if (isNaN(num) || num === 0) return 'N/A';
    if (num >= 1e12) return '$' + (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return '$' + (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return '$' + (num / 1e6).toFixed(2) + 'M';
    return '$' + num.toFixed(2);
}

// Tooltip helpers
function showTooltip(event, d) {
    if (d.sector === 'ETF') return;
    const tooltip = d3.select('#tooltip');
    tooltip
        .classed('visible', true)
        .html(
            '<strong>' + d.ticker + '</strong><br/>' +
            (d['full name'] || 'N/A') + '<br/>' +
            'Sector: ' + d.sector
        )
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 10) + 'px');
}

function hideTooltip() {
    d3.select('#tooltip').classed('visible', false);
}

// Selection sync between bubble chart and table
function selectStock(ticker) {
    selectedTicker = ticker;
    d3.selectAll('.bubble').classed('selected', d => d.ticker === ticker);
    d3.selectAll('#stock-table tbody tr').classed('selected', d => d.ticker === ticker);
}

// Load data and build visualizations
d3.csv('data/stock-descriptions.csv').then(function(data) {
    // Parse market cap
    data.forEach(function(d) {
        d.marketCap = +d.marketCap || 0;
    });

    stockData = data;
    createBubbleChart(data);
    createTable(data);
    createLegend();
});

function createLegend() {
    var legend = d3.select('#legend');
    Object.entries(sectorColors).forEach(function(entry) {
        var sector = entry[0], color = entry[1];
        var item = legend.append('div').attr('class', 'legend-item');
        item.append('div').attr('class', 'legend-color').style('background-color', color);
        item.append('span').text(sector);
    });
}

function createBubbleChart(data) {
    var width = 700;
    var height = 600;
    var padding = 80;

    var svg = d3.select('#bubble-chart')
        .attr('width', width)
        .attr('height', height);

    // Radius scale based on market cap
    var maxMarketCap = d3.max(data.filter(function(d) { return d.marketCap > 0; }), function(d) { return d.marketCap; });
    var radiusScale = d3.scaleSqrt()
        .domain([0, maxMarketCap])
        .range([15, 50]);

    // Define cluster centers — arrange in a pentagon shape centered in the canvas
    var cx = width / 2, cy = height / 2;
    var clusterRadius = 120;
    var sectors = ['Energy', 'Financial', 'Industry', 'Information Technology', 'ETF'];
    var sectorCenters = {};
    sectors.forEach(function(s, i) {
        var angle = (i * 2 * Math.PI / sectors.length) - Math.PI / 2;
        sectorCenters[s] = {
            x: cx + clusterRadius * Math.cos(angle),
            y: cy + clusterRadius * Math.sin(angle)
        };
    });

    // Prepare nodes
    var nodes = data.map(function(d) {
        return {
            id: d.ticker,
            ticker: d.ticker,
            'full name': d['full name'],
            sector: d.sector,
            marketCap: d.marketCap,
            radius: d.sector === 'ETF' ? 15 : radiusScale(d.marketCap),
            x: cx,
            y: cy,
            clusterX: sectorCenters[d.sector].x,
            clusterY: sectorCenters[d.sector].y
        };
    });

    // Force simulation
    var simulation = d3.forceSimulation(nodes)
        .force('charge', d3.forceManyBody().strength(-5))
        .force('collision', d3.forceCollide().radius(function(d) { return d.radius + 2; }))
        .force('x', d3.forceX(function(d) { return d.clusterX; }).strength(0.4))
        .force('y', d3.forceY(function(d) { return d.clusterY; }).strength(0.4));

    // Draw bubbles (circles)
    var bubbles = svg.selectAll('.bubble')
