     2|
     3|import { createContext, useContext, useState, ReactNode } from 'react';
     4|
     5|type Theme = 'light' | 'dark';
     6|
     7|const ThemeContext = createContext<{
     8|  theme: Theme;
     9|  toggleTheme: () => void;
    10|}>({ theme: 'light', toggleTheme: () => {} });
    11|
    12|export function useTheme() {
    13|  return useContext(ThemeContext);
    14|}
    15|
    16|export function ThemeProvider({ children }: { children: ReactNode }) {
    17|  const [theme, setTheme] = useState<Theme>('light');
    18|
    19|  const toggleTheme = () => {
    20|    const newTheme = theme === 'light' ? 'dark' : 'light';
    21|    setTheme(newTheme);
    22|    localStorage.setItem('theme', newTheme);
    23|    document.documentElement.setAttribute('data-theme', newTheme);
    24|    const el = document.getElementById('theme-wrapper');
    25|    if (el) {
    26|      el.style.backgroundColor = newTheme === 'dark' ? '#1a1a1a' : '#ffffff';
    27|      el.style.color = newTheme === 'dark' ? '#ffffff' : '#000000';
    28|    }
    29|  };
    30|
    31|  return (
    32|    <ThemeContext.Provider value={{ theme, toggleTheme }}>
    33|      <div data-testid="theme-wrapper" id="theme-wrapper" className="min-h-screen">
    34|        {children}
    35|      </div>
    36|      <script
    37|        dangerouslySetInnerHTML={{
    38|          __html: `(function(){try{var t=localStorage.getItem('theme')||'light';document.documentElement.setAttribute('data-theme',t);var el=document.getElementById('theme-wrapper');if(el){el.style.backgroundColor=t==='dark'?'#1a1a1a':'#ffffff';el.style.color=t==='dark'?'#ffffff':'#000000';}}catch(e){}})();`,
    39|        }}
    40|      />
    41|    </ThemeContext.Provider>
    42|  );
    43|}
