{"content": "package clusterdata.datatypes;

import java.io.Serializable;

/**
 * Task event types from Google cluster data.
 */
public enum EventType {
    SUBMIT(0),
    SCHEDULE(1),
    EVICT(2),
    FAIL(3),
    FINISH(4),
    KILL(5),
    LOST(6),
    UPDATE_PENDING(7),
    UPDATE_RUNNING(8);

    EventType(int eventCode) {
        this.value = eventCode;
    }

    private final int value;
    private static final java.util.Map<Integer, EventType> MAP = new java.util.HashMap<>();

    static {
        for (EventType e : EventType.values()) {
            MAP.put(e.value, e);
        }
    }

    public static EventType valueOf(int eventType) {
        return MAP.get(eventType);
    }

    public int getValue() {
        return value;
    }
}
