{"content": "#!/usr/bin/env python3
"""Debug: print closed_at dates for bug issues."""

import json
import os
import time
import urllib.request
import urllib.error
from datetime import datetime
from pathlib import Path

REPO = "cli/cli"
START = "2024-12-01"
END = "2024-12-31"
DATE_RANGE = f"created:{START}..{END}"

TOKEN = os.environ.get("GH_TOKEN") or os.environ.get("GITHUB_TOKEN")

HEADERS = {
    "Accept": "application/vnd.github.v3+json",
    "User-Agent": "SkillsBench-Agent",
}
if TOKEN:
    HEADERS["Authorization"] = f"Bearer {TOKEN}"


def fetch_search(q, per_page=100):
    url = f"https://api.github.com/search/issues?q=repo:{REPO}+{q}&per_page={per_page}"
    all_items = []
    page = 1
    retries = 0
    while url:
        req = urllib.request.Request(url, headers=HEADERS)
        try:
            with urllib.request.urlopen(req) as resp:
                data = json.loads(resp.read())
        except urllib.error.HTTPError as e:
            if e.code == 403 and retries < 5:
                wait = int(e.headers.get("X-RateLimit-Reset", "0")) - int(time.time()) + 1
                wait = max(wait, 30)
                print(f"Rate limited, sleeping {wait}s...")
                time.sleep(wait)
                retries += 1
                continue
            raise
        items = data.get("items", [])
        total = data.get("total_count", 0)
        all_items.extend(items)
        print(f"  Fetched page {page}, got {len(items)} items (total={total})")
        link = resp.headers.get("Link", "")
        if "next" not in link:
            break
        for part in link.split(","):
            if 'rel="next"' in part:
                url = part.split(";")[0].strip().strip("<>").strip()
                break
        else:
            break
        page += 1
    return all_items


def has_bug_label(labels):
    return any("bug" in l["name"].lower() for l in labels)


def main():
    print("Fetching Issues...")
    issue_items = fetch_search("type:issue+" + DATE_RANGE)

    bugs_with_state = []
    for item in issue_items:
        is_bug = has_bug_label(item.get("labels", []))
        if is_bug:
            bugs_with_state.append({
                "number": item["number"],
                "state": item["state"],
                "closed_at": item.get("closed_at"),
                "title": item["title"][:50],
            })

    closed_bugs = [b for b in bugs_with_state if b["state"] == "closed"]

    # Check closed_at in December range
    def in_december(dt_str):
        if not dt_str:
            return False
        fmt = "%Y-%m-%dT%H:%M:%SZ"
        try:
            dt = datetime.strptime(dt_str, fmt)
            return datetime(2024, 12, 1) <= dt <= datetime(2024, 12, 31, 23, 59, 59)
        except:
            return False

    bugs_closed_in_dec = [b for b in bugs_with_state if b.get("closed_at") and in_december(b["closed_at"])]

    print(f"\nTotal bugs: {len(bugs_with_state)}")
    print(f"Bugs currently closed (any time): {len(closed_bugs)}")
    print(f"Bugs closed_at in December 2024: {len(bugs_closed_in_dec)}")
    print()
    print("BUGS closed_at in December:")
    for b in bugs_closed_in_dec:
        print(f"  #{b['number']} closed_at={b['closed_at']} - {b['title']}")
    print()
    print("BUGS closed_at NOT in December (currently closed):")
    for b in closed_bugs:
        if b["number"] not in [x["number"] for x in bugs_closed_in_dec]:
            print(f"  #{b['number']} closed_at={b['closed_at']} - {b['title']}")
    print()
    print("BUGS still open:")
    for b in bugs_with_state:
        if b["state"] == "open":
            print(f"  #{b['number']} closed_at={b['closed_at']} - {b['title']}")


if __name__ == "__main__":
    main()
