"""

import os
import re
import time
from decimal import Decimal
from PIL import Image
from rapidocr_onnxruntime import RapidOCR
from openpyxl import Workbook


def _ocr_image(image_path):
    """OCR an image using rapidocr - single pass only."""
    engine = RapidOCR()
    try:
        result_data, elapsed = engine(image_path)
        if result_data:
            return "\n".join(item[1].strip() for item in result_data)
    except Exception:
        pass
