def _parse_date_any_format(date_text):
    """Parse date string from receipt OCR output."""
    from datetime import datetime
    normalized = date_text.strip()
    normalized = normalized.replace("O", "0").replace("o", "0")
    normalized = normalized.replace('\u2212', '-').replace('\u2013', '-').replace('\u2014', '-')
    normalized = normalized.replace("I", "1").replace("l", "1")
    normalized = normalized.replace(" ", "")
    candidates = [
        "%d/%m/%Y", "%d-%m-%Y", "%d/%m/%y", "%d-%m-%y",
        "%m/%d/%Y", "%m-%d-%Y", "%m/%d/%y", "%m-%d-%y",
        "%Y/%m/%d", "%Y-%m-%d",
    ]
    for fmt in candidates:
        try:
            dt = datetime.strptime(normalized, fmt)
            if 2000 <= dt.year <= 2030:
                return dt
        except ValueError:
            continue
    return None


def _extract_date_from_text(text):
    """Extract date from OCR text."""
    if not text:
        return None
    found_dates = []
    date_patterns = [
        (re.compile(r"DATE[:\s]*(\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4})", re.IGNORECASE), True),
        (re.compile(r"TARIKH[:\s]*(\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4})", re.IGNORECASE), True),
        (re.compile(r"(\d{1,2}[/\-]\d{1,2}[/\-]\d{4})"), False),
        (re.compile(r"(\d{1,2}[/\-]\d{1,2}[/\-]\d{2})"), False),
    ]
    for pat, has_context in date_patterns:
        for match in pat.findall(text):
            dt = _parse_date_any_format(match)
            if dt:
                found_dates.append((dt, has_context))
    if not found_dates:
        return None
    return found_dates[0][0]


# Money regex: captures numbers with a dot and exactly 2 decimal digits
_MONEY_RE = re.compile(r"(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})")


def _extract_total_from_text(text):
    """Extract total from receipt.

    Strategy:
    1. Find all lines matching total keywords
    2. Filter out subtotal/tax/summary lines
    3. Extract amount from same line or next 1-3 lines
    4. Pick highest priority match
    """
    if not text:
        return None

    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]

    _EXCLUDE_RE = re.compile(r"(?:SUB\s*TOTAL|SUBTOTAL)", re.IGNORECASE)

    candidates = []  # (value, priority, line_index)

    for i, line in enumerate(lines):
        upper = line.upper().strip()

        # Skip excluded lines
        if _EXCLUDE_RE.search(line):
            continue

        # Skip "CHANGE" / "CASH TENDERED"
        if re.match(r"\s*CHANGE\b", line, re.I):
            continue
        if re.match(r"\s*CASH\s+TENDERED", line, re.I):
            continue

        # Skip "Total" in GST Summary section (bottom of receipt)
        # These are typically the last occurrence of "Total" and appear near "Amount\nTax\nSR@6%"
        if _is_gst_summary_total(line, lines, i):
            continue

        # Score the line
        priority = _score_total_line(line)
        if priority <= 0:
            continue

        # Find money on this line and next 1-3 lines
        nums = _MONEY_RE.findall(line)
        if nums:
            try:
                val = Decimal(nums[-1].replace(",", ""))
                candidates.append((val, priority, i))
            except Exception:
                pass

        # Lookahead: look for amount on next 1-3 lines
        for j in range(i + 1, min(i + 1 + 3, len(lines))):
            next_line = lines[j]
            # Don't scan past new section indicators
            if re.match(r"^\s*THANK|^\s*GOODS?\s+SOLD|^\s*Keep\s+the|^\s*$", next_line, re.I):
                break
            next_nums = _MONEY_RE.findall(next_line)
            if next_nums:
                try:
                    val = Decimal(next_nums[-1].replace(",", ""))
                    pri = max(priority - 3, 1)
                    candidates.append((val, pri, i))
                except Exception:
                    pass
                # Only use the first line with numbers
                break

    if not candidates:
        return None

    # Sort: highest priority first, then latest line (later total = more likely to be grand total)
    candidates.sort(key=lambda x: (x[1], x[2]), reverse=True)
    return candidates[0][0]


def _is_gst_summary_total(line, lines, idx):
    """Detect if this 'Total' is in the GST Summary section at the bottom of receipt."""
    # Check if the line is simply "Total" and appears near GST Summary
    if not re.match(r"^\s*Total\s*$", line):
        return False

    # Look backwards: is there a "GST Summary" header nearby within last 15 lines?
    for j in range(max(0, idx - 15), idx):
        if re.search(r"GST\s*SUMMARY", lines[j], re.I):
            return True

    return False


def _score_total_line(line):
    """Score a line for how likely it is the grand total line."""
    upper = line.upper().strip()

    # "TOTAL RM" / "TOTAL : RM"
    if re.search(r"TOTAL\s*:?\s*RM\s*:", line, re.I):
        return 90
    if re.search(r"TOTAL\s*:?\s*RM\b", line, re.I):
        return 80

    # GRAND TOTAL (including "GRANDTOTAL" as one word)
    if re.search(r"GRAND\s*TOTAL", line, re.I):
        return 75

    # TOTAL AMOUNT
    if re.search(r"TOTAL\s*AMOUNT", line, re.I):
        return 70

    # TOTAL DUE / BALANCE DUE
    if re.search(r"TOTAL\s*DUE|BALANCE\s*DUE|AMOUNT\s*DUE", line, re.I):
        return 65

    # NETT/NET TOTAL
    if re.search(r"NETT?\s*TOTAL", line, re.I):
        return 60

    # Total Rounding / TotalRounded / TotalAmtRounded
    if re.search(r"TOTAL.*ROUNDED", line, re.I) or "TOTALROUNDED" in upper:
        return 55

    # Total Gross / TotalGross
    if re.search(r"TOTAL\s*GROSS", line, re.I):
        return 50

    # "Total Sales Incl GST" - this is the real total for some receipts
    if re.search(r"TOTAL\s*SALES", line, re.I):
        return 45

    # "Total After Adj" 
    if re.search(r"TOTAL.*AFTER.*ADJ", line, re.I):
        return 44

    # "Total Incl.of GST/CGT" 
    if re.search(r"TOTAL\s*INCL", line, re.I):
        return 42

    # "Total Excl.of GST" - not the final total
    if re.search(r"TOTAL\s*EXCL", line, re.I):
        return 20

    # Specific: "Total (RM) :"
    if re.search(r"TOTAL\s*\(?\s*RM\s*\)?\s*:", line, re.I):
        return 40

    # General "TOTAL" (but exclude some edge cases)
    if re.search(r"\bTOTAL\b", line, re.I):
        # Skip if line contains "incl" or "inclusive" (these are label lines, e.g. "TOTAL INCLUDES 6% GST")
        if re.search(r"(?:INCL|INCLUDES)", line, re.I):
            return 5
        # Skip "Total" in GST Summary section
        if re.search(r"(?:GST|TAX)\s+TOTAL", line, re.I):
            return 10
        return 35

    # Rounded alone
    if re.search(r"\bROUNDED\b", line, re.I):
        return 25

    return 0


def main():
    dataset_dir = "/tmp/workspace/dataset/img"
    out_path = "/tmp/workspace/stat_ocr.xlsx"

    import sys

    exts = {".jpg", ".jpeg", ".png", ".tif", ".tiff", ".webp", ".bmp"}
    entries = sorted(os.listdir(dataset_dir))

    results = {}
    for entry in entries:
        _, ext = os.path.splitext(entry)
        if ext.lower() not in exts:
            continue
        fp = os.path.join(dataset_dir, entry)

        print(f"Processing: {entry}...", flush=True, file=sys.stderr)
        text = _ocr_image(fp)

        if not text:
            results[entry] = {"date": None, "total_amount": None}
            continue

        dt = _extract_date_from_text(text)
        amount = _extract_total_from_text(text)

        date_str = dt.strftime("%Y-%m-%d") if dt else None
        amount_str = f"{amount:.2f}" if amount else None

        results[entry] = {"date": date_str, "total_amount": amount_str}
        print(f"  -> date={date_str}, amount={amount_str}", flush=True, file=sys.stderr)

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for filename in sorted(results.keys()):
        row = results[filename]
        ws.append([filename, row.get("date"), row.get("total_amount")])
    wb.save(out_path)
    print(f"\nSaved to {out_path}", flush=True, file=sys.stderr)

    for fn in sorted(results.keys()):
        print(f"{fn}: date={results[fn]['date']}, amount={results[fn]['total_amount']}")


if __name__ == "__main__":
    main()
