q02_rows.sort(key=lambda r: r["run_id"])
write_json("q02.json", q02_rows)

# Q03 - Peak
failing_runs: List[str] = []
min_peak_by_run: Dict[str, Dict[str, Any]] = {}

for rid in all_runs:
