        by.setdefault(str(r["run_id"]), r)

    exp_ids = run_ids(df_runs.reset_index())
    missing = [rid for rid in exp_ids if rid not in by]
    assert not missing, f"Q04 missing run_ids: {missing}"

    ids_in_out = [str(r.get("run_id")) for r in out if isinstance(r, dict) and r.get("run_id") is not None]
    assert ids_in_out == sorted(ids_in_out), "Q04 must be sorted by run_id"

    for rid in exp_ids:
        r = by[rid]
        actual = round2(float(df_runs.loc[rid, "conveyor_speed_cm_min"]))
        got_actual = r.get("actual_speed_cm_min", r.get("actual_speed", None))
        assert got_actual is not None, f"Q04 missing actual speed for {rid}"
        assert_float_close(got_actual, actual, msg=f"Q04 speed mismatch for {rid}")

        meets = r.get("meets", r.get("feasible", None))
        assert isinstance(meets, bool), f"Q04 meet must be boolean for {rid}"

    print("Q04 PASSED")

def test_Q05():
    df_runs = load_runs()
    out = load_json(ALL_Q[4])
    assert isinstance(out, list), "Q05 must be a JSON list"

    fam_to_runs = {}
    for bf, g in df_runs.groupby("board_family"):
