{"code": "import re
import html.parser

class PGTextExtractor(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.text_parts = []
        self.skip_tags = {'script', 'style', 'head', 'nav', 'meta', 'link', 'img'}
        self.in_skip = 0

    def handle_starttag(self, tag, attrs):
        if tag in self.skip_tags:
            self.in_skip += 1

    def handle_endtag(self, tag):
        if tag in self.skip_tags and self.in_skip > 0:
            self.in_skip -= 1

    def handle_data(self, data):
        if self.in_skip == 0:
            text = data.strip()
            if text:
                self.text_parts.append(text)

def extract_text(html_content):
    parser = PGTextExtractor()
    parser.feed(html_content)
