// Higher-Kinded Type Simulation / Functor & Monad
// ============================================================================

/**
 * Functor for tokens.
 *
 * Scala can express true higher-kinded types, making this a proper functor.
 */
class TokenFunctor[A] private (private val _wrapped: Option[A]) {

  def map[B](func: A => B): TokenFunctor[B] =
    new TokenFunctor(_wrapped.map(func))

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] =
    _wrapped.fold(new TokenFunctor[B](None))(func)

  def getOrElse(default: => A): A =
    _wrapped.getOrElse(default)

  def get: A = _wrapped.getOrElse(throw new NoSuchElementException("TokenFunctor is empty"))
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = new TokenFunctor(Some(value))
}

/**
 * Monad for tokens with extended operations.
 */
class TokenMonad[A] private (wrapped: Option[A]) extends TokenFunctor[A](wrapped) {

  override def map[B](func: A => B): TokenMonad[B] =
    new TokenMonad(wrapped.map(func))

  override def flatMap[B](func: A => TokenFunctor[B]): TokenMonad[B] =
    new TokenMonad(wrapped.flatMap(v => func(v) match {
      case tm: TokenMonad[B] => tm._wrapped
      case tf => Some(tf.get)
    }))

  /**
   * Applicative apply.
   */
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(for {
      f <- funcWrapped._wrapped
      v <- wrapped
    } yield f(v))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(Some(value))
  def apply[A](value: A): TokenMonad[A] = new TokenMonad(Some(value))
}

