     3|/**
     4| * Creates a cylinder mesh that connects two points in 3D space.
     5| * This is a utility function used to model beams, legs, and spokes.
     6| * @param {THREE.Vector3} point1 - The starting point of the cylinder.
     7| * @param {THREE.Vector3} point2 - The ending point of the cylinder.
     8| * @param {number} radius - The radius of the cylinder.
     9| * @param {string} name - The name for the resulting mesh.
    10| * @returns {THREE.Mesh} A mesh representing the cylinder beam.
    11| */
    12|function createCylinderBeam(point1, point2, radius, name) {
    13|    // This vector represents the direction and length of the cylinder.
    14|    const direction = new THREE.Vector3().subVectors(point2, point1);
    15|    const length = direction.length();
    16|
    17|    // Create the cylinder geometry. By default, it's aligned with the Y-axis.
    18|    const geometry = new THREE.CylinderGeometry(radius, radius, length, 16);
    19|    const mesh = new THREE.Mesh(geometry);
    20|    mesh.name = name;
    21|
    22|    // The default THREE.CylinderGeometry is oriented along the Y axis.
    23|    // We need to rotate it to align with the direction vector from point1 to point2.
    24|    // We compute a quaternion that represents the rotation from the default Y-axis to our target direction.
    25|    const Y_AXIS = new THREE.Vector3(0, 1, 0);
    26|    mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.clone().normalize());
    27|
    28|    // After rotating, we position the cylinder's center exactly halfway between the two points.
    29|    mesh.position.copy(point1).add(direction.multiplyScalar(0.5));
    30|
    31|    return mesh;
