   100|    const frontRightBracePoint = new THREE.Vector3().lerpVectors(frontRightFoot, frontAxlePoint, crossBraceHeight / (axleHeight - supportBaseHeight));
   101|    const backLeftBracePoint = new THREE.Vector3().lerpVectors(backLeftFoot, backAxlePoint, crossBraceHeight / (axleHeight - supportBaseHeight));
   102|    const backRightBracePoint = new THREE.Vector3().lerpVectors(backRightFoot, backAxlePoint, crossBraceHeight / (axleHeight - supportBaseHeight));
