DATA_DIR = '/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/travel-planning/environment/data'

def _extract_cities(current_city):
    parts = []
    if not current_city:
        return parts
    lowered = current_city.replace(' to ', '|').replace(' from ', '|')
    for piece in lowered.split('|'):
        cleaned = piece.strip().strip(',')
        if cleaned:
            parts.append(cleaned)
    return parts

results = []

# Test 1: File exists
ok = os.path.exists(PLAN_PATH)
results.append(('test_plan_file_exists', ok))
if not ok:
    print('FAIL: test_plan_file_exists')
    exit(1)

# Test 2: Structure and length
with open(PLAN_PATH) as f:
    payload = json.load(f)
ok = isinstance(payload, dict) and 'plan' in payload and isinstance(payload['plan'], list) and len(payload['plan']) == 7
results.append(('test_plan_structure_and_length', ok))
if not ok:
    print('FAIL: test_plan_structure_and_length')
    exit(1)

plan = payload['plan']

# Test 3: Required fields and days
required = {'day', 'current_city', 'transportation', 'breakfast', 'lunch', 'dinner', 'attraction', 'accommodation'}
ok = True
for idx, day in enumerate(plan, start=1):
    if not isinstance(day, dict):
        ok = False; break
    missing = required - set(day.keys())
    if missing:
        ok = False; break
    if day['day'] != idx:
        ok = False; break
results.append(('test_plan_required_fields_and_days', ok))

# Test 4: No flights
ok = True
for idx, day in enumerate(plan, start=1):
    transport = day.get('transportation', '') or ''
    if 'flight' in transport.lower():
        ok = False; break
results.append(('test_no_flights_in_transportation', ok))

# Test 5: Starts in Minneapolis
day1_city = str(plan[0].get('current_city', '')).lower()
ok = 'minneapolis' in day1_city
results.append(('test_starts_in_minneapolis', ok))

# Test 6: At least 3 cities
cities = []
for day in plan:
    cities.extend(_extract_cities(str(day.get('current_city', ''))))
unique_cities = {c.lower() for c in cities if c}
ok = len(unique_cities) >= 3
results.append(('test_visits_at_least_three_cities', ok))

# Test 7: Ohio cities
ohio_cities = {'cleveland', 'columbus', 'cincinnati', 'toledo', 'akron', 'dayton'}
ohio_matches = unique_cities & ohio_cities
ok = len(ohio_matches) > 0
results.append(('test_visits_ohio_cities', ok))

# Test 8: Pet-friendly
pet_keywords = ['pet', 'dog', 'cat', 'animal']
pet_hints = []
for day in plan:
    acc = str(day.get('accommodation', '')).lower()
    if any(kw in acc for kw in pet_keywords):
        pet_hints.append(day.get('accommodation', ''))
ok = len(pet_hints) > 0
results.append(('test_pet_friendly_accommodation_hint', ok))

# Test 9: Attractions non-empty
ok = True
for idx, day in enumerate(plan, start=1):
    attraction = str(day.get('attraction', '')).strip()
    if not attraction or attraction == '-':
        ok = False; break
results.append(('test_attractions_non_empty', ok))

# Test 10: Tool calls
assert 'tool_called' in payload
tools = payload['tool_called']
normalized = {str(t).strip().lower() for t in tools}
required_tools = {'search_cities', 'search_accommodations', 'search_restaurants', 'search_attractions', 'search_driving_distance'}
missing = [t for t in required_tools if t not in normalized]
ok = len(missing) == 0
results.append(('test_tool_calls_present', ok))

# Test 11: Cuisines (cross-reference from data)
restaurant_path = Path(DATA_DIR) / 'restaurants' / 'clean_restaurant_2022.csv'
restaurant_cuisines = {}
if restaurant_path.exists():
