        return 0
    val = data_ws.cell(row=series_to_row[series_code], column=year_to_col[year]).value
    return val if val is not None else 0

# Export data: rows 12-17
export_series = {
    12: '466BXGS_BP6.A', 13: '419BXGS_BP6.A', 14: '443BXGS_BP6.A',
