}

EXPECTED_GDP = {
    26: [418.0, 349.5, 415.2, 507.1, 504.2],
    27: [38.7, 34.6, 39.3, 44.4, 44.7],
    28: [138.7, 107.5, 141.8, 182.8, 161.8],
    29: [176.4, 144.4, 179.7, 236.3, 234.2],
    30: [88.1, 75.9, 88.2, 114.7, 109.1],
    31: [838.6, 734.3, 874.2, 1108.6, 1067.6],
}

TOLERANCE = 0.5
errors = []
for row in range(12, 18):
    for i, year in enumerate(years):
        exp = EXPECTED_EXPORTS[row][i]
        got = computed_exports[row][i]
        if abs(got - exp) > TOLERANCE:
            errors.append(f"Export row {row} year {year}: expected {exp}, got {got}")

for row in range(19, 25):
    for i, year in enumerate(years):
        exp = EXPECTED_IMPORTS[row][i]
        got = computed_imports[row][i]
        if abs(got - exp) > TOLERANCE:
            errors.append(f"Import row {row} year {year}: expected {exp}, got {got}")

for row in range(26, 32):
    for i, year in enumerate(years):
        exp = EXPECTED_GDP[row][i]
        got = computed_gdp[row][i]
        if abs(got - exp) > TOLERANCE:
            errors.append(f"GDP row {row} year {year}: expected {exp}, got {got}")

if errors:
    print("ERRORS FOUND:")
    for e in errors:
        print(f"  {e}")
else:
    print("ALL EXPECTED VALUES MATCH!")

# Now compute net exports as % GDP
EXPECTED_NET_EXPORTS_PCT = {
    35: [19.7, 21.9, 25.2, 24.8, 23.2],
    36: [11.3, 5.6, 19.5, 25.9, 17.3],
    37: [12.6, 5.6, 22.4, 30.1, 20.9],
