    gdp_row = 26 + (row - 35)
    computed_net[row] = []
    for i, year in enumerate(years):
        exp_val = lookup(export_series[export_row], year)
        imp_val = lookup(import_series[import_row], year)
        gdp_val = lookup(gdp_series[gdp_row], year)
        if gdp_val != 0:
