    p75 = sv[3] + 0.75 * (sv[4] - sv[3])
    computed_stats[col_idx] = {
        'MIN': min_v, 'MAX': max_v, 'MEDIAN': med_v,
        'AVG': round(avg_v, 1), 'P25': p25, 'P75': p75
    }

# Note: Excel's PERCENTILE uses different interpolation method
# Let me also check what Excel produces (linear interpolation)
# Python's numpy.percentile vs Excel's PERCENTILE function
# Excel PERCENTILE uses: rank = percentile*(n-1) + 1 (1-indexed)
# For k=0.25: rank = 0.25*5+1 = 2.25 -> value at index 2 + 0.25*(value at 3 - value at 2)  (0-indexed: index 1 + 0.25*(index2-index1))
# wait, let me recalculate properly

# Excel PERCENTILE algorithm for 6 data points:
# The formula is: rank = p * (n-1) + 1, where p is the percentile (0 to 1)
# Interpolate between the two surrounding values
for col_idx in range(5):
    vals = [computed_net[row][col_idx] for row in range(35, 41)]
    sv = sorted(vals)
    n = len(sv)

    # Excel PERCENTILE(p): rank = (n-1)*p, interpolate between floor and ceil
    rank25 = (n-1) * 0.25  # = 5 * 0.25 = 1.25
    rank75 = (n-1) * 0.75  # = 5 * 0.75 = 3.75

    def excel_percentile(sorted_vals, p):
        n = len(sorted_vals)
        rank = (n-1) * p
        lower = int(rank)
        upper = lower + 1
        frac = rank - lower
        if upper >= n:
            return sorted_vals[lower]
        return sorted_vals[lower] + frac * (sorted_vals[upper] - sorted_vals[lower])

    p25_e = excel_percentile(sv, 0.25)
    p75_e = excel_percentile(sv, 0.75)
    computed_stats[col_idx]['P25_EXCEL'] = p25_e
    computed_stats[col_idx]['P75_EXCEL'] = p75_e

errors3 = []
for stat_name, stat_row in [(42, 'MIN'), (43, 'MAX'), (44, 'MEDIAN'), (45, 'AVG')]:
